function patternHalfDiamond(n) {
  let rows = [];
  for (let i = 0; i < 2 * n - 1; i++) {
    let row = '';
    const limit = i < n ? i + 1 : 2 * n - 1 - i;
    for (let j = 0; j < limit; j++) {
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

