function patternHalfDiamond(n) {
  let rows = [];
  for (let i = 0; i < 2 * n - 1; i++) {
    const stars = i < n ? i + 1 : 2 * n - 1 - i;
    rows.push('*'.repeat(stars));
  }
  return rows.join('\n');
}
